module mux4to1 (
    input [3:0] in,
    input [1:0] sel,
    output out
);
    wire not_sel0, not_sel1;
    wire term0, term1, term2, term3;

    not not0(not_sel0, sel[0]);
    not not1(not_sel1, sel[1]);

    and and0(term0, in[0], not_sel1, not_sel0);
    and and1(term1, in[1], not_sel1, sel[0]);
    and and2(term2, in[2], sel[1], not_sel0);
    and and3(term3, in[3], sel[1], sel[0]);

    or or0(out, term0, term1, term2, term3);
endmodule

module mux4to1 (
    input [3:0] in,
    input [1:0] sel,
    output out
);
    wire not_s0, not_s1;
    wire t0, t1, t2, t3;

    // Invert select signals
    not(not_s0, sel[0]);
    not(not_s1, sel[1]);

    // AND terms for each input
    and(t0, in[0], not_s1, not_s0);
    and(t1, in[1], not_s1, sel[0]);
    and(t2, in[2], sel[1], not_s0);
    and(t3, in[3], sel[1], sel[0]);

    // Combine all terms with OR
    or(out, t0, t1, t2, t3);
endmodule

module mux4to1 (
    input [3:0] in,
    input [1:0] sel,
    output out
);
    // Generate negated select signals
    wire not_s1 = ~sel[1];
    wire not_s0 = ~sel[0];

    // Generate selection terms
    wire term0 = not_s1 & not_s0;
    wire term1 = not_s1 & sel[0];
    wire term2 = sel[1] & not_s0;
    wire term3 = sel[1] & sel[0];

    // Combine terms with OR gates
    wire or1 = term0 | term1;
    wire or2 = term2 | term3;
    wire final_or = or1 | or2;

    // Final AND with in
    assign out = in[0] & or1 & in[1] & or2 & in[2] & in[3];
endmodule

