module bin_to_gray (
    input [3:0] binary,
    output [3:0] gray
);

    wire [1:0] a = binary[3:2];
    wire [1:0] b = binary[1:0];

    // XOR for gray[3] and gray[2]
    assign gray[3] = a[0] ^ a[1];
    assign gray[2] = a[0] ^ b[0];

    // Example AND-NOT operations for lower bits (assumed)
    assign gray[1] = a[1] & ~b[1];
    assign gray[0] = a[1] & ~b[0];

