module traffic_light (
    input clk, reset,
    output [2:0] light
);

    // State definitions
    localparam [1:0] W = 2'b00,
                     X = 2'b01,
                     Y = 2'b10;

    reg [1:0] current_state, next_state;

    // State register with synchronous reset
    always @(posedge clk) begin
        if (reset)
            current_state <= W;
        else
            current_state <= next_state;
    end

    // Next state logic
    always @(*) begin
        case (current_state)
            W: next_state = X;
            X: next_state = Y;
            Y: next_state = W;
            default: next_state = W; // Handle unexpected states
        endcase
    end

    // Output logic based on current state
    always @(*) begin
        case (current_state)
            W: light = 3'b100;
            X: light = 3'b010;
            Y: light = 3'b001;
            default: light = 3'b000; // Default case
        endcase
    end

endmodule

module traffic_light (
    input clk, reset,
    output [2:0] light
);

    reg Q0, Q1, Q2;
    wire T0, T1, T2;

    // Compute T values
    assign T0 = 1'b1; // T0 is always 1
    assign T1 = Q0 | reset;
    assign T2 = Q1 & Q0;

    // Update flip-flops on rising clock edge
    always @(posedge clk) begin
        Q0 <= T0 ? 1'b1 : Q0;
        Q1 <= T1 ? 1'b1 : Q1;
        Q2 <= T2 ? 1'b1 : Q2;
    end

    // Output logic
    assign light[0] = reset & Q0 & Q1 & Q2;
    assign light[1] = reset & (Q0 | Q1 | Q2);
    assign light[2] = reset | (Q0 & Q1 & Q2);

endmodule

module traffic_light (
    input clk, reset,
    output [2:0] light
);

// Define states
localparam S0 = 2'd0,
           S1 = 2'd1,
           S2 = 2'd2;

reg [1:0] current_state, next_state;

// State register
always @(posedge clk) begin
    if (reset)
        current_state <= S0;
    else
        current_state <= next_state;
end

// Next state logic
always @(*) begin
    case (current_state)
        S0: next_state = S1;
        S1: next_state = S2;
        S2: next_state = S0;
        default: next_state = S0;
    endcase
end

// Output logic
assign light = (current_state == S0) ? 3'b100 :
            (current_state == S1) ? 3'b110 :
            (current_state == S2) ? 3'b010 :
            3'b000;

endmodule

module elevator_controller (
    input clk, reset,
    input up_request, down_request,
    output [1:0] state
);

reg [1:0] Q, Qn;

// Direct D flip-flops
always @(posedge clk or posedge reset) begin
    if (reset) begin
        Q <= 2'b00;
    end else begin
        Q <= {up_request, down_request};
    end
end

// Negative edge D flip-flops with NAND-based master latch
always @(negedge clk or posedge reset) begin
    if (reset) begin
        Qn <= 2'b00;
    end else begin
        case ({up_request, down_request})
            2'b00: Qn <= 2'b00;
            2'b01: Qn <= 2'b01;
            2'b10: Qn <= 2'b10;
            2'b11: Qn <= 2'b11;
            default: Qn <= 2'b00;
        endcase
    end
end

// Master latch using NAND gates
wire S = ~(Q[0] & up_request);
wire R = ~(Q[1] & down_request);
wire Q_master, Qn_master;

nand(Q_master, S, Qn_master);
nand(Qn_master, R, Q_master);

assign state = {Q_master, Qn_master};

endmodule

module elevator_controller (
    input clk, reset,
    input up_request, down_request,
    output [1:0] state
);

    parameter S0 = 2'b00,
              S1 = 2'b01,
              S2 = 2'b10;

    reg [1:0] current_state, next_state;

    always @(posedge clk or posedge reset) begin
        if (reset)
            current_state <= S0;
        else
            current_state <= next_state;
    end

    always @(*) begin
        case (current_state)
            S0: next_state = up_request ? S1 : S0;
            S1: begin
                if (down_request)
                    next_state = S0;
                else if (up_request)
                    next_state = S2;
                else
                    next_state = S1;
            end
            S2: next_state = up_request ? S2 : S1;
            default: next_state = S0;
        endcase
    end

    assign state = current_state;

endmodule

