module elevator_controller (
    input clk, reset,
    input up_request, down_request,
    output [1:0] state
);

    parameter State1 = 2'b00,
              State2 = 2'b01,
              State3 = 2'b10;

    reg [1:0] current_state, next_state;

    always @(posedge clk or posedge reset) begin
        if (reset)
            current_state <= State1;
        else
            current_state <= next_state;
    end

    always @(*) begin
        case (current_state)
            State1: begin
                if (up_request)
                    next_state = State2;
                else if (down_request)
                    next_state = State3;
                else
                    next_state = State1;
            end
            State2: begin
                if (!up_request)
                    next_state = State1;
                else
                    next_state = State2;
            end
            State3: begin
                if (!down_request)
                    next_state = State1;
                else
                    next_state = State3;
            end
            default: next_state = State1;
        endcase
    end

    assign state = current_state;

endmodule

module vending_machine (
    input clk, reset,
    input coin_inserted, item_selected,
    output [1:0] state
);

    // State definitions
    localparam [1:0] STATE_AWAITSTART_0 = 2'b00,
                     STATE_AWAITSTART_1 = 2'b01,
                     STATE_STARTGAME_0  = 2'b10,
                     STATE_STARTGAME_1  = 2'b11;

    reg [1:0] current_state, next_state;

    // Sequential state transition
    always @(posedge clk or posedge reset) begin
        if (reset) begin
            current_state <= STATE_AWAITSTART_0;
        end else begin
            current_state <= next_state;
        end
    end

    // Combinational next state logic
    always @(*) begin
        case (current_state)
            STATE_AWAITSTART_0: begin
                next_state = item_selected ? STATE_AWAITSTART_1 : STATE_AWAITSTART_0;
            end
            STATE_AWAITSTART_1: begin
                next_state = item_selected ? STATE_STARTGAME_0 : STATE_AWAITSTART_1;
            end
            STATE_STARTGAME_0: begin
                next_state = coin_inserted ? STATE_STARTGAME_1 : STATE_STARTGAME_0;
            end
            STATE_STARTGAME_1: begin
                next_state = coin_inserted ? STATE_AWAITSTART_0 : STATE_STARTGAME_1;
            end
            default: next_state = STATE_AWAITSTART_0;
        endcase
    end

    // Output current state
    assign state = current_state;

endmodule

module vending_machine (
    input clk, reset,
    input coin_inserted, item_selected,
    output [1:0] state
);

    // State definitions
    localparam [1:0] A = 2'b00,
                     B = 2'b01,
                     C = 2'b10,
                     D = 2'b11;

    reg [1:0] current_state, next_state;

    // Sequential logic for state transition
    always @(posedge clk or posedge reset) begin
        if (reset) begin
            current_state <= A;
        end else begin
            current_state <= next_state;
        end
    end

    // Combinational logic for next state
    always @(*) begin
        if (coin_inserted) begin
            case (current_state)
                A: next_state = B;
                B: next_state = C;
                C: next_state = D;
                D: next_state = D;
                default: next_state = A;
            endcase
        end else if (item_selected) begin
            case (current_state)
                A: next_state = B;
                B: next_state = C;
                C: next_state = D;
                D: next_state = A;
                default: next_state = A;
            endcase
        end else begin
            next_state = current_state;
        end
    end

    // Output assignment
    assign state = current_state;

endmodule

