module up_counter8(
    input clk,
    input rst,
    output [7:0] count
);
    reg [7:0] q;
    wire [7:0] t;

    assign t[0] = 1'b1;

    genvar i;
    generate
        for (i = 1; i < 8; i = i + 1) begin : gen_toggle
            assign t[i] = &q[i-1:0];
        end
    endgenerate

    always @(posedge clk) begin
        if (rst) begin
            q <= 8'b0;
        end else begin
            for (integer j = 0; j < 8; j = j + 1) begin
                q[j] <= q[j] ^ t[j];
            end
        end
    end

    assign count = q;
endmodule

module TopModule (
  input clk,
  input resetn,
  input  [2:0] r,
  output [2:0] g
);

// State definitions
localparam [1:0] r_100k = 2'b00,
                 r_1k  = 2'b01,
                 r_10k = 2'b10,
                 r_100k_rst = 2'b11;

reg [1:0] current_state, next_state;

// State register
always @(posedge resetn) begin
  if (clk)
    current_state <= r_100k;
  else
    current_state <= next_state;
end

// Next state logic
always @(*) begin
  case (current_state)
    r_100k: begin
      if (r[0])
        next_state = r_1k;
      else if (r[1])
        next_state = r_10k;
      else if (r[2])
        next_state = r_100k_rst;
      else
        next_state = r_100k;
    end
    r_1k: begin
      if (r[0])
        next_state = r_10k;
      else if (r[1])
        next_state = r_100k_rst;
      else if (r[2])
        next_state = r_100k;
      else
        next_state = r_1k;
    end
    r_10k: begin
      if (r[0])
        next_state = r_100k_rst;
      else if (r[1])
        next_state = r_100k;
      else if (r[2])
        next_state = r_1k;
      else
        next_state = r_10k;
    end
    r_100k_rst:
      next_state = r_100k;
    default:
      next_state = r_100k;
  endcase
end

// Output logic
assign g = (current_state == r_100k) ? 3'b000 :
           (current_state == r_1k)  ? 3'b001 :
           (current_state == r_10k) ? 3'b010 :
           3'b011;

endmodule

module TopModule (
  input clk,
  input resetn,
  input  [2:0] r,
  output [2:0] g
);

  localparam [1:0] ready = 2'b00,
                   gnt1  = 2'b01,
                   gnt2  = 2'b10,
                   gnt3  = 2'b11;

  reg [1:0] state, next_state;

  always @(posedge resetn) begin
    if (clk)
      state <= ready;
    else
      state <= next_state;
  end

  always @(*) begin
    case (state)
      ready: begin
        if (r[0])
          next_state = gnt1;
        else if (r[1])
          next_state = gnt2;
        else if (r[2])
          next_state = gnt3;
        else
          next_state = ready;
      end
      gnt1:  next_state = r[0] ? gnt1 : ready;
      gnt2:  next_state = r[1] ? gnt2 : ready;
      gnt3:  next_state = r[2] ? gnt3 : ready;
      default: next_state = ready;
    endcase
  end

  assign g = (state == ready) ? 3'b000 :
                     (state == gnt1) ? 3'b001 :
                     (state == gnt2) ? 3'b010 :
                     (state == gnt3) ? 3'b100 :
                     3'b000;

endmodule

module TopModule (
  input clk,
  input resetn,
  input  [2:0] r,
  output [2:0] g
);

  // State definitions
  localparam GREEN  = 2'b00;
  localparam YELLOW = 2'b01;
  localparam RED    = 2'b10;
  localparam STOP   = 2'b11;

  reg [1:0] current_state, next_state;

  // State register
  always @(posedge resetn) begin
    if (clk)
      current_state <= GREEN;
    else
      current_state <= next_state;
  end

  // Next state logic
  always @(*) begin
    case (current_state)
      GREEN:  next_state = (r == 3'd4) ? YELLOW : GREEN;
      YELLOW: next_state = (r == 3'd2) ? RED   : YELLOW;
      RED:    next_state = (r == 3'd4) ? STOP   : RED;
      STOP:   next_state = (r == 3'd2) ? GREEN  : STOP;
      default: next_state = GREEN;
    endcase
  end

  // Output logic
  assign g = (current_state == GREEN)  ? 3'b001 :
                     (current_state == YELLOW) ? 3'b011 :
                     (current_state == RED)    ? 3'b101 :
                     3'b111;

endmodule

module TopModule (
  input clk,
  input resetn,
  input  [2:0] r,
  output [2:0] g
);

  reg [2:0] current_state, next_state;

  localparam [2:0] C1 = 3'b000,
                   C2 = 3'b001,
                   C3 = 3'b010,
                   C4 = 3'b011,
                   C5 = 3'b100;

  // State register
  always @(posedge resetn) begin
    if (clk)
      current_state <= C1;
    else
      current_state <= next_state;
  end

  // Next state logic
  always @(*) begin
    case (current_state)
      C1: begin
        if (r[0])
          next_state = C2;
        else if (r[1])
          next_state = C3;
        else if (r[2])
          next_state = C4;
        else
          next_state = C1;
      end
      C2: begin
        if (r[0])
          next_state = C3;
        else if (r[1])
          next_state = C1;
        else if (r[2])
          next_state = C4;
        else
          next_state = C2;
      end
      C3: begin
        if (r[0])
          next_state = C4;
        else if (r[1])
          next_state = C2;
        else if (r[2])
          next_state = C5;
        else
          next_state = C3;
      end
      C4: begin
        if (r[0])
          next_state = C5;
        else if (r[1])
          next_state = C3;
        else if (r[2])
          next_state = C5;
        else
          next_state = C4;
      end
      C5: begin
        if (r[0])
          next_state = C1;
        else if (r[1])
          next_state = C3;
        else if (r[2])
          next_state = C5;
        else
          next_state = C5;
      end
      default: next_state = C1;
    endcase
  end

  // Output logic
  assign g = (current_state == C5) ? 3'b100 : 3'b000;

endmodule

