  input b,
  input sel_b1,
  input sel_b2,
  output out_assign,
  output reg out_always
);

  wire selected_data;

  // Combinational logic to select between a and b based on sel_b1 and sel_b2
  assign selected_data = (sel_b1 && !sel_b2) ? a :
                         (!sel_b1 && sel_b2) ? b :
                         1'b0;

  // Tri-state control for out_assign and out_always
  always @(*) begin
    if (sel_b1 && sel_b2) begin
      out_assign = 1'bz;
      out_always = 1'bz;
    end else begin
      out_assign = selected_data;
      out_always = selected_data;
    end
  end

