    left = 0;
    down = 0;
    right = 0;
    up = 0;

    case (scancode)
      16'h0000: left = 1;   // Load PC
      16'h0001: down = 1;   // Increment PC
      16'h0002: right = 1;     // Write to register
      16'h0003: up = 1;    // Write to memory
      default: ;               // Default case leaves all outputs as 0
    endcase
  end

