  always @(*) begin
    case (scancode)
      16'h0000: begin // ADD
        left = 1'b1;
        down    = 1'b0;
        right = 1'b0;
        up   = 1'b1;
      end
      16'h0001: begin // SUB
        left = 1'b1;
        down    = 1'b1;
        right = 1'b0;
        up   = 1'b1;
      end
      16'h0002: begin // AND
        left = 1'b1;
        down    = 1'b0;
        right = 1'b0;
        up   = 1'b1;
      end
      16'h0003: begin // OR
        left = 1'b1;
        down    = 1'b0;
        right = 1'b0;
        up   = 1'b1;
      end
      16'h0004: begin // JUMP
        left = 1'b0;
        down    = 1'b0;
        right = 1'b1;
        up   = 1'b0;
      end
      default: begin // Default: ADD behavior
        left = 1'b0;
        down    = 1'b0;
        right = 1'b0;
        up   = 1'b0;
      end
    endcase
  end

