module TopModule (
  input clk,
  input areset,
  input train_valid,
  input train_taken,
  output logic [1:0] state
);

  // State definitions
  localparam [1:0] STATE_0 = 2'b00,
                   STATE_1 = 2'b01,
                   STATE_2 = 2'b10,
                   STATE_3 = 2'b11;

  reg [1:0] current_state, next_state;

  // State register with asynchronous reset
  always @(posedge clk or posedge areset) begin
    if (areset)
      current_state <= STATE_1;
    else
      current_state <= next_state;
  end

  // Next state logic
  always @* begin
    if (train_valid && !train_taken) begin
      case (current_state)
        STATE_0: next_state = STATE_1;
        STATE_1: next_state = STATE_2;
        STATE_2: next_state = STATE_3;
        STATE_3: next_state = STATE_3;
        default: next_state = STATE_1;
      endcase
    end
    else
      next_state = current_state;
  end

  // Output assignment
  assign state = current_state;

endmodule

module TopModule (
  input clk,
  input areset,
  input train_valid,
  input train_taken,
  output logic [1:0] state
);

  // Define state parameters
  localparam S0 = 2'b01,
             S1 = 2'b10,
             S2 = 2'b11;

  reg [1:0] current_state, next_state;

  // Sequential logic for state transitions and reset
  always @(posedge clk or posedge areset) begin
    if (areset) begin
      current_state <= S0;
    end else begin
      current_state <= next_state;
    end
  end

  // Combinational logic for next state based on inputs
  always @(*) begin
    next_state = current_state; // Default to stay in current state
    if (train_valid && train_taken) begin
      case (current_state)
        S0: next_state = S1;
        S1: next_state = S2;
        S2: next_state = S0;
        default: next_state = S0; // Handle undefined states
      endcase
    end
  end

  // Output the current state
  assign state = current_state;

endmodule

module TopModule (
  input clk,
