  always @(posedge clk or posedge areset) begin
    if (areset)
      current_state <= UP;
    else
      current_state <= next_state;
  end

  always @(*) begin
    next_state = current_state;
    if (train_valid && train_taken) begin
      case (current_state)
        UP: next_state = RIGHT;
        RIGHT: next_state = DOWN;
