  localparam [1:0] c0 = 2'b00,
                   c1 = 2'b01,
                   c2 = 2'b10,
                   c3 = 2'b11;

  reg [1:0] state;

  // State transitions and reset
  always @(posedge clk or posedge areset) begin
    if (areset) begin
      state <= c1;
    end else if (train_valid) begin
      if (train_taken) begin
        case (state)
          c1: state <= c2;
          c2: state <= c3;
          c3: state <= c0;
          c0: state <= c1;
          default: state <= c1;
        endcase
