module TopModule (
  input clk,
  input aresetn,
  input x,
  output reg z
);
  // Define states
  localparam MainState = 2'b00;
  localparam State1 = 2'b01;
  localparam State2 = 2'b10;

  reg [1:0] current_state, next_state;

  // State transition logic
  always @(posedge clk or negedge aresetn) begin
    if (!aresetn) begin
      current_state <= MainState;
    end else begin
      current_state <= next_state;
    end
  end

  // Next state logic
  always @(*) begin
    case (current_state)
      MainState: next_state = x ? State1 : MainState;
      State1: next_state = x ? State2 : MainState;
      State2: next_state = x ? State2 : MainState;
      default: next_state = MainState;
    endcase
  end

  // Output logic (Mealy: depends on current state and input)
  always @(*) begin
    z = (current_state == State1) && x;
  end

endmodule

