module TopModule (
  input clk,
  input aresetn,
  input x,
  output reg z
);

  localparam s0 = 2'b00,
             s1 = 2'b01,
             s2 = 2'b10;

  reg [1:0] current_state, next_state;

  always @(posedge clk or negedge aresetn) begin
    if (!aresetn)
      current_state <= s0;
    else
      current_state <= next_state;
  end

  always @(*) begin
    next_state = s0;
    z = 0;
    case (current_state)
      s0: begin
        next_state = x ? s1 : s0;
        z = 0;
      end
      s1: begin
        next_state = x ? s1 : s2;
        z = 0;
      end
      s2: begin
        if (x) begin
          next_state = s1;
          z = 1;
        end else begin
          next_state = s0;
          z = 0;
        end
      end
      default: begin
        next_state = s0;
        z = 0;
      end
    endcase
  end

endmodule

