module TopModule (
  input [7:0] a,
  input [7:0] b,
  output [7:0] s,
  output overflow
);

  wire [7:0] p, g;
  wire [8:0] carry;

  assign p = a ^ b;
  assign g = a & b;

  assign carry[0] = 1'b0;

  genvar i;
  generate
    for (i = 0; i < 8; i = i + 1) begin: adder_stage
      assign s[i] = p[i] ^ carry[i];
      assign carry[i + 1] = g[i] | (p[i] & carry[i]);
    end
  endgenerate

  assign overflow = carry[8];

endmodule

module TopModule (
  input [7:0] a,
  input [7:0] b,
  output [7:0] s,
  output overflow
);

  wire [7:0] p, g;
  wire [7:0] carry;

  assign p = a ^ b;
  assign g = a & b;

  assign carry[0] = g[0];

  genvar i;
  generate
    for (i = 1; i < 8; i = i + 1) begin : gen_carry
      assign carry[i] = g[i] | (p[i] & carry[i-1]);
    end
  endgenerate

  assign s = p ^ carry;
  assign overflow = carry[7];

endmodule

module TopModule (
  input [7:0] a,
  input [7:0] b,
  output [7:0] s,
  output overflow
);

  wire [7:0] p;
  wire [8:0] c;

  assign p = a ^ b;

  assign c[0] = 1'b0;

  genvar i;
  generate
    for (i = 0; i < 8; i = i + 1) begin : adder_loop
      wire nand1_out, nand2_out, nand3_out, nand4_out, nand5_out;

      nand(nand1_out, p[i], p[i]);
      nand(nand2_out, p[i], a[i]);
      nand(nand3_out, p[i], b[i]);
      nand(nand4_out, nand2_out, nand3_out);
      nand(nand5_out, c[i], p[i]);
      nand(s[i], nand4_out, nand5_out);

      if (i < 7) begin
        nand(c[i + 1], nand4_out, nand5_out);
      end
    end
  endgenerate

  assign overflow = c[8];

endmodule

