module TopModule (
  input clk,
  input in,
  input reset,
  output out
);

  parameter state_lower = 1'b0;
  parameter state_upper = 1'b1;

  reg current_state;
  reg next_state;

  // Combinational next state logic
  always @(*) begin
    next_state = current_state ^ in;
  end

  // Sequential state transition and reset
  always @(posedge clk) begin
    if (reset) begin
      current_state <= state_lower;
    end else begin
      current_state <= next_state;
    end
  end

  // Output assignment
  assign out = current_state;

endmodule

