module TopModule (
  input clk,
  input j,
  input k,
  input areset,
  output out
);

  localparam STATE_STOPPED = 1'b0;
  localparam STATE_RUNNING = 1'b1;

  reg state;
  reg next_state;

  // State register
  always @(posedge clk or posedge areset) begin
    if (areset)
      state <= STATE_STOPPED;
    else
      state <= next_state;
  end

  // Next state logic
  always @(*) begin
    case (state)
      STATE_STOPPED: next_state = j ? STATE_RUNNING : STATE_STOPPED;
      STATE_RUNNING: next_state = k ? STATE_STOPPED : STATE_RUNNING;
      default: next_state = STATE_STOPPED;
    endcase
  end

  // Output logic
  assign out = (state == STATE_RUNNING);

endmodule

