module TopModule (
  input [3:0] x,
  input [3:0] y,
  output [4:0] sum
);

  wire [3:0] P, G;
  wire c1, c2, c3, c4;
  wire sum0, sum1, sum2, sum3;

  assign P = x ^ y;
  assign G = x & y;

  // Carry calculations
  assign c1 = G[0];
  assign c2 = G[1] | (P[1] & G[0]);
  assign c3 = G[2] | (P[2] & G[1]) | (P[2] & P[1] & G[0]);
  assign c4 = G[3] | (P[3] & G[2]) | (P[3] & P[2] & G[1]) | (P[3] & P[2] & P[1] & G[0]);

  // Sum calculations
  assign sum0 = P[0];               // c0 is 0
  assign sum1 = P[1] ^ c1;
  assign sum2 = P[2] ^ c2;
  assign sum3 = P[3] ^ c3;

  assign sum = {c4, sum3, sum2, sum1, sum0};

endmodule

module TopModule (
