      S1: next_state = reset ? S2 : S0;
      S2: next_state = reset ? S2 : S3;
      S3: next_state = reset ? S4 : S0;
      S4: next_state = reset ? S2 : S0;
      default: next_state = S0;
    endcase
  end

  // Output logic (Moore: depends only on current state)
  assign z = (current_state == S3 || current_state == S4);

endmodule

