  assign transformed[0] = code[0] ^ code[1];
  assign transformed[1] = code[1] ^ code[2];
  assign transformed[2] = code[2] ^ code[3];
  assign transformed[3] = code[3] ^ code[4];
  assign transformed[4] = code[4] ^ code[0];

  // Encoding by duplicating transformed bits
  assign encoded[0]  = transformed[0];
  assign encoded[1]  = transformed[0];
  assign encoded[2]  = transformed[1];
  assign encoded[3]  = transformed[1];
  assign encoded[4]  = transformed[2];
  assign encoded[5]  = transformed[2];
