module TopModule (
  input clk,
  input reset,
  input w,
  output z
);
  reg [2:0] S, next_S;

  // State register (sequential logic)
  always @(posedge clk) begin
    if (reset)
      S <= 3'b000;
    else
      S <= next_S;
  end

  // Next state logic (combinational)
  always @(*) begin
    case (S)
      3'b000: next_S = w ? 3'b100 : 3'b001;
      3'b001: next_S = w ? 3'b011 : 3'b010;
      3'b010: next_S = w ? 3'b011 : 3'b101;
      3'b011: next_S = w ? 3'b001 : 3'b100;
      3'b100: next_S = w ? 3'b001 : 3'b010;
      3'b101: next_S = w ? 3'b011 : 3'b010;
      default: next_S = 3'b000; // Recover from undefined states
    endcase
  end

  // Output logic (high when in state 100)
  assign z = S[2];
endmodule

module TopModule (
