  input areset,
  input x,
  output z
);

  reg [1:0] current_state, next_state;

  localparam [1:0] reset_state = 2'b00,
                   flopped1_state = 2'b01,
                   flopped2_state = 2'b10,
                   stable_state = 2'b11;

  // State transition logic
  always @* begin
    case (current_state)
      reset_state:   next_state = x ? flopped1_state : reset_state;
      flopped1_state: next_state = x ? flopped2_state : reset_state;
      flopped2_state: next_state = x ? stable_state : reset_state;
      stable_state:   next_state = x ? stable_state : reset_state;
      default:        next_state = reset_state;
    endcase
  end

  // State register
  always @(posedge clk or posedge areset) begin
    if (areset)
      current_state <= reset_state;
    else
      current_state <= next_state;
  end

  // Output logic
  assign z = (current_state == stable_state) ? 1'b1 :
               (current_state == flopped2_state) ? x :
               1'b0;

endmodule

