    S1       = 3'd1,
    S2       = 3'd2,
    S3       = 3'd3,
    T1       = 3'd4,
    T2       = 3'd5,
    T3       = 3'd6,
    U1       = 3'd7;

  reg [2:0] current_state, next_state;

