  always @(posedge clk) begin
    if (reset)
      current_state <= RST;
    else
      current_state <= next_state;
  end

  // Combinational next state logic
  always @(*) begin
    case (current_state)
      RST: next_state = in ? S1 : RST;
      S1: next_state = in ? S2 : S1;
      S2: next_state = in ? T1 : S2;
      T1: next_state = in ? T2 : T1;
      T2: next_state = in ? T3 : T2;
      T3: next_state = in ? U1 : T3;
      U1: next_state = in ? U1 : S3;
      S3: next_state = in ? RST : S3;
      default: next_state = RST;
    endcase
  end

  // Output assignments
  assign disc = (current_state == S3);
  assign flag = (current_state == T3);
  assign err = (current_state == U1);

