  end

  // Next state logic
  always @(*) begin
    case (current_state)
      INIT: next_state = in ? P1 : INIT;
      P1:   next_state = in ? P1 : P2;
      P2:   next_state = in ? GAME : P2;
      GAME: next_state = GAME;
      default: next_state = INIT;
    endcase
  end

  // Score and win logic
  always @(posedge clk) begin
    if (reset) begin
      score_reg <= 3'b0;
      win_reg <= 0;
    end else begin
      if (current_state == INIT && in)
        score_reg <= 3'b0;
      else if (current_state == P1 && in)
        score_reg <= score_reg + 1;
      else if (current_state == P2 && in)
        win_reg <= 1;
