module TopModule (
  input clk,
  input in,
  input reset,
  output done
);

  // Define states
  localparam S0 = 2'b00,
             S1 = 2'b01,
             S2 = 2'b10,
             S3 = 2'b11;

  reg [1:0] current_state, next_state;
  reg trigger_out;
  reg [2:0] counter;

  // State register
  always @(posedge clk) begin
    if (reset) begin
      current_state <= S0;
    end else begin
      current_state <= next_state;
    end
  end

  // Next state logic (combinational)
  always @(*) begin
    case (current_state)
      S0: next_state = in ? S1 : S0;
      S1: next_state = (counter == 3'd4) ? S2 : S1;
      S2: next_state = S3;
      S3: next_state = S3;
      default: next_state = S0;
    endcase
  end

  // Counter logic (sequential)
  always @(posedge clk) begin
    if (reset) begin
      counter <= 3'b0;
    end else begin
      if (current_state == S1) begin
        counter <= (counter < 3'd4) ? counter + 1 : 3'b0;
      end else begin
        counter <= 3'b0;
      end
    end
  end

  // Trigger logic (sequential)
  always @(posedge clk) begin
    if (reset) begin
      trigger_out <= 1'b0;
    end else begin
      trigger_out <= (current_state == S2) ? 1'b1 : 1'b0;
    end
  end

  // Tri-state output
  assign done = reset ? 1'bz : trigger_out;

endmodule

module TopModule (
