  input bump_right,
  input ground,
  output walk_left,
  output walk_right,
  output aaah
);

  localparam [1:0] IDLE = 2'b00,
                   PLAY = 2'b01,
                   GAMEOVER = 2'b10,
                   WIN = 2'b11;

  reg [1:0] current_state, next_state;

  always @(posedge clk or posedge areset) begin
    if (areset) current_state <= IDLE;
    else current_state <= next_state;
  end

  always @(*) begin
    case (current_state)
      IDLE: next_state = bump_left ? PLAY : IDLE;
      PLAY: begin
        if (ground)
          next_state = (bump_right) ? WIN : GAMEOVER;
        else
          next_state = PLAY;
      end
      GAMEOVER: next_state = (!bump_left) ? IDLE : GAMEOVER;
      WIN: next_state = (!bump_left) ? IDLE : WIN;
      default: next_state = IDLE;
    endcase
  end

  assign walk_left = (current_state == PLAY);
  assign walk_right = (current_state == GAMEOVER);
  assign aaah = (current_state == IDLE) || (current_state == WIN);

endmodule

module TopModule (
  input clk,
  input areset,
  input bump_left,
  input bump_right,
  input ground,
  output walk_left,
  output walk_right,
  output aaah
);

  // State definitions
  localparam [1:0] RESET   = 2'b00,
                   WAIT_A  = 2'b01,
                   WAIT_B  = 2'b10,
                   DARK    = 2'b11;

  reg [1:0] current_state, next_state;

  // Sequential logic
  always @(posedge clk or posedge areset) begin
    if (areset) current_state <= RESET;
    else     current_state <= next_state;
  end

  // Combinational next state logic
  always @(*) begin
    case (current_state)
      RESET:  next_state = WAIT_A;
      WAIT_A: begin
        if (~bump_right)
          next_state = DARK;
        else if (ground)
          next_state = WAIT_B;
        else
          next_state = WAIT_A;
      end
      WAIT_B: begin
        if (~ground)
          next_state = DARK;
        else if (bump_left)
          next_state = WAIT_A;
        else
          next_state = WAIT_B;
      end
      DARK:   next_state = DARK;
      default: next_state = RESET;
    endcase
  end

  // Output logic
  assign walk_left  = (current_state == WAIT_A);
  assign walk_right  = (current_state == WAIT_B);
  assign aaah = (current_state == RESET) || (current_state == DARK);

endmodule

