	// Synchronizer for data input
	always @(posedge clk_a or negedge clk_b) begin
		if (!clk_b) begin
			data_sync <= 4'b0;
		end else begin
			data_sync <= {data_sync[2:0], brstn};
		end
	end

	// Update output with synchronized data when enabled
	always @(posedge clk_a or negedge clk_b) begin
		if (!clk_b) begin
			dataout <= 4'b0;
		end else if (data_en) begin
			dataout <= data_sync;
		end
	end

endmodule

module synchronizer(
