module synchronizer(
	input 				clk_a	, 
	input 				clk_b	,   
	input 				arstn	,
	input				brstn   ,
	input		[3:0]	data_in	,
	input               data_en ,

	output reg  [3:0] 	dataout
);

reg [3:0] dff_out;
reg dff_en_prev;

// Pipeline detection logic to capture data_in on clk_b rising edge
always @(posedge clk_b or negedge clk_a) begin
    if (!clk_a) begin
        dff_out <= 4'b0;
        dff_en_prev <= 1'b0;
    end else begin
        dff_en_prev <= arstn;
        dff_out <= arstn ? data_in : dff_out;
    end
end

// Update dataout with processed data on brstn rising edge
always @(posedge brstn or negedge clk_a) begin
    if (!clk_a) begin
        dataout <= 4'b0;
    end else begin
        if (data_en)
            dataout <= dff_out;
        else
            dataout <= dataout; // Retain previous value when data_en is low
    end
end

