module synchronizer(
	input 				clk_a	, 
	input 				clk_b	,   
	input 				arstn	,
	input				brstn   ,
	input		[3:0]	data_in	,
	input               data_en ,

	output reg  [3:0] 	dataout
);

reg [3:0] stage1, stage2;
reg prev_enable;

always @(posedge clk_a or negedge clk_b) begin
	if (!clk_b) begin
		stage1 <= 4'b0;
		stage2 <= 4'b0;
		prev_enable <= 1'b0;
		dataout <= 4'b0;
		end
	else begin
		// Stage1: Capture input data
		stage1 <= data_in;

		// Stage2: Capture stage1 data when enabled
		stage2 <= stage1;

		// Track previous data_en for edge detection
		prev_enable <= data_en;

		// Update output on data_en rising edge
		if (data_en && !prev_enable)
			dataout <= stage2;
	end
end

endmodule

module synchronizer(
	input 				clk_a	, 
	input 				clk_b	,   
	input 				arstn	,
	input				brstn   ,
	input		[3:0]	data_in	,
	input               data_en ,

	output reg  [3:0] 	dataout
);

reg [3:0] stage1, stage2;
reg prev_stage1_wb_en;

always @(posedge clk_a or negedge clk_b) begin
	if (!clk_b) begin
		stage1 <= 4'b0;
		stage2 <= 4'b0;
		prev_stage1_wb_en <= 1'b0;
		dataout <= 4'b0;
		end
	else begin
		// Capture stage1 from current data_in when brstn is high
		if (brstn) begin
			stage2 <= stage1;
		end

		// Update stage1 with new data_in data when data_en is high
		if (data_en) begin
			stage1 <= data_in;
		end

		// Track previous stage1 value for edge detection
		prev_stage1_wb_en <= stage1;

		// Update output only when previous stage1 was 0 (rising edge)
		if (!prev_stage1_wb_en && stage1) begin
			dataout <= stage1;
		end
	end
end

endmodule

module fsm(IN,MATCH,CLK,RST);
input IN,CLK,RST;
output reg MATCH;

// Define states
localparam [2:0] INIT  = 3'b000,
                 GET0  = 3'b001,
                 GET1  = 3'b010,
                 COMP  = 3'b011,
                 UPDATE0 = 3'b100,
                 UPDATE1 = 3'b101;

reg [2:0] current_state, next_state;

// State transitions
always @(*) begin
    case (current_state)
        INIT:  next_state = RST ? GET0 : INIT;
        GET0:  next_state = RST ? GET1 : GET0;
        GET1:  next_state = RST ? COMP : GET1;
        COMP:  next_state = IN ? UPDATE1 : UPDATE0;
        UPDATE0: next_state = INIT;
        UPDATE1: next_state = INIT;
        default: next_state = INIT;
    endcase
end

// State register
always @(posedge CLK, posedge RST) begin
    if (RST) current_state <= INIT;
    else current_state <= next_state;
end

// Output logic
always @(*) begin
    MATCH = (current_state == COMP) ? 1'b0 : 1'b1;
end

endmodule

module fsm(IN,MATCH,CLK,RST);
input IN,CLK,RST;
output reg MATCH;

reg [4:0] current_state, next_state;

// Next state logic based on permutation cycling
always @(*) begin
    if (CLK) begin
        case(current_state)
            5'b00000: next_state = 5'b00001; // 0 → 1
            5'b00001: next_state = 5'b00010; // 1 → 2
            5'b00010: next_state = 5'b00100; // 2 → 4
            5'b00100: next_state = 5'b01000; // 4 → 8
            5'b01000: next_state = 5'b10000; // 8 → 16 (mod 32)
            5'b10000: next_state = 5'b00000; // 16 → 0
            default: next_state = 5'b00000; // Handle unexpected states
        endcase
    end else begin
        next_state = current_state;
    end
end

// State register with asynchronous reset
always @(posedge RST, posedge IN) begin
    if (IN)
        current_state <= 5'b00000;
    else
        current_state <= next_state;
end

// Output logic: MATCH=1 when current state is 16
always @(posedge RST or posedge IN) begin
    if (IN)
        MATCH <= 1'b0;
    else
        MATCH <= (current_state == 5'b10000);
end

endmodule

module fsm(IN,MATCH,CLK,RST);
