module fsm(IN,MATCH,CLK,RST);
input IN,CLK,RST;
output reg MATCH;

reg [1:0] state;

always @(posedge CLK, posedge RST) begin
    if (RST) begin
        state <= 2'b00;
        MATCH <= 1'b0;
    end else begin
        case (state)
            2'b00: state <= (IN) ? 2'b01 : 2'b00;
            2'b01: state <= (IN) ? 2'b10 : 2'b00;
            2'b10: state <= (IN) ? 2'b10 : 2'b00;
            default: state <= 2'b00;
        endcase
    end
end

