    if (RST) begin
        MATCH <= 1'b0;
    end else begin
        case (state)
            2'b00: MATCH <= 1'b0;
            2'b01: MATCH <= (IN) ? 1'b1 : 1'b0;
            2'b10: MATCH <= (IN) ? 1'b1 : 1'b0;
            default: MATCH <= 1'b0;
        endcase
    end
end

endmodule

