module sequence_detector(
     input  clk, 
     input  rst_n,
     input  data_in, 
     output sequence_detected				
     );

     // Define states
     localparam [2:0] IDLE        = 3'b000,
                      CHECK_HIGH  = 3'b001,
                      HIGH_STATE  = 3'b010,
                      CHECK_LOW   = 3'b011,
                      LOW_STATE   = 3'b100;

     reg [2:0] state, next_state;

     // State transition (sequential)
     always @(posedge clk or negedge rst_n) begin
         if (!rst_n) begin
             state <= IDLE;
         end else begin
             state <= next_state;
         end
     end

     // Next state logic (combinational)
     always @(*) begin
         case (state)
             IDLE: begin
                 next_state = (data_in) ? CHECK_HIGH : IDLE;
             end
             CHECK_HIGH: begin
                 next_state = (data_in) ? HIGH_STATE : IDLE;
             end
             HIGH_STATE: begin
                 next_state = (~data_in) ? CHECK_LOW : HIGH_STATE;
             end
             CHECK_LOW: begin
                 next_state = (~data_in) ? LOW_STATE : HIGH_STATE;
             end
             LOW_STATE: begin
                 next_state = (data_in) ? CHECK_HIGH : LOW_STATE;
             end
             default: next_state = IDLE;
         endcase
     end

     // Output logic (sequence_detected is high in HIGH_STATE)
     assign sequence_detected = (state == HIGH_STATE);

endmodule

